import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type * as React from "react";

/**
 * The Sistine material system — the single source of the material → markup mapping.
 *
 * FIVE materials (glass, frosted, crystal, chakra, opaque), each a `[data-material]` token set in
 * app/theme/materials.css, composed with orthogonal AXES (border + its colour, veil, size, gradient, glow, sheen)
 * over the one structural `glass` utility. Components call `glassMaterial()` instead of hardcoding
 * recipe class strings (check-theme bans the legacy `glass-bg`/`glass-surface`/… classes).
 *
 * Semantics:
 * - `material` UNDEFINED = adaptive: no attribute is rendered; the surface follows the page's
 *   [data-glass] style (the default everywhere).
 * - An explicit material PINS the element under any page style, and — because the token set is
 *   inherited custom properties — also acts as a scoped default for adaptive glass descendants
 *   (a dialog set to frosted re-skins the controls inside it; pin a child back with its own material).
 * - `"none"` = not a glass surface: the helper returns nothing and the component supplies its plain
 *   (shadcn) classes.
 */
export type Material = "glass" | "frosted" | "crystal" | "chakra" | "opaque" | "none";

export interface MaterialProps {
  /** undefined = adaptive (follows the page style); "none" = the component's plain fallback. */
  material?: Material;
  /** Material border. Three weights: `true`/"hairline" = the material's edge (1px; 0.5px under
   *  frosted), "rim" = 2px, "frame" = 4px. */
  border?: boolean | "hairline" | "rim" | "frame";
  /** The border's COLOUR. "glass" (the default) = the material's own edge, a near-white rim at the
   *  material's alpha, which reads as glass but disappears on light themes at any weight. "ink" = the
   *  page's text colour (--foreground, at --glass-border-ink-a), a visible line wherever text is legible.
   *  Pairs with `border`; under the opaque page style it also colours the uniform panel edge. */
  borderColor?: "glass" | "ink";
  /** Element-composed legibility floor for read-through overlays (menus, tooltips, toasts). */
  veil?: boolean;
  /** Blur/elevation tier — INTERNAL: set by a component's ROLE (glass-sm/-lg), not a public prop
   *  ("size" universally means a component's dimensions; the material tier must never shadow that). */
  size?: "sm" | "lg" | "xl";
  /** Readability blur FLOOR (>= --glass-diffuse, default 12px) for text-dense translucent surfaces;
   *  inert under opaque. "stained" = the dyed mode: same floor, plus true stained-glass optics — the
   *  backdrop renders as TONAL SHADES of the theme hue (grayscale luminance collapse — the tint supplies the color). */
  diffuse?: boolean | "stained";
  /** Brand-gradient accent layered over the material. */
  gradient?: boolean;
  /** Resting glow, or the intensified "lg" halo. */
  glow?: boolean | "lg";
  /** Opt-in hover shimmer (pseudo-element based — avoid on sticky/fixed surfaces). */
  sheen?: boolean;
}

/** The PUBLIC per-instance axis props a component spreads onto its type. Excludes `size` (the material
 *  blur tier is a role-internal detail — a component's own `size` prop owns that name). */
export type MaterialAxisProps = Omit<MaterialProps, "size">;

/** The `rest` side of splitAxisProps. Distributes over union props (DayPicker's mode union, Radix
 *  ToggleGroup's single/multiple) so a discriminated union survives the split instead of collapsing
 *  under a bare Omit. */
export type SplitAxisRest<P> = P extends unknown ? Omit<P, keyof MaterialAxisProps> : never;

/** Split the material axis props off a component's props in ONE place — components never enumerate
 *  axis keys, so a NEW axis is zero-touch: extend MaterialProps + this destructure, done. `size` is
 *  role-internal (not in MaterialAxisProps) and stays in `rest` for the component's own cva. */
export function splitAxisProps<P extends MaterialAxisProps>(
  props: P,
): [
  MaterialAxisProps,
  SplitAxisRest<P>,
] {
  const { material, border, borderColor, veil, diffuse, gradient, glow, sheen, ...rest } = props;
  return [
    {
      material,
      border,
      borderColor,
      veil,
      diffuse,
      gradient,
      glow,
      sheen,
    },
    /* The conditional (distributive) rest type can't be proven for an unresolved P — safe by
     * construction: rest is exactly P minus the axis keys. */
    rest as SplitAxisRest<P>,
  ];
}

export interface MaterialAttrs {
  /** Spread-ready: undefined for adaptive and "none". */
  "data-material"?: Exclude<Material, "none">;
  /** "" when material === "none" (caller supplies its plain classes). */
  className: string;
}

export function glassMaterial(props: MaterialProps = {}): MaterialAttrs {
  const { material, border, borderColor, veil, size, diffuse, gradient, glow, sheen } = props;
  if (material === "none") {
    return {
      className: "",
    };
  }
  return {
    "data-material": material,
    className: [
      "glass",
      border && "glass-border",
      border === "rim" && "glass-border-rim",
      border === "frame" && "glass-border-frame",
      borderColor === "ink" && "glass-border-ink",
      veil && "glass-veil",
      size === "sm" && "glass-sm",
      size === "lg" && "glass-lg",
      size === "xl" && "glass-xl",
      diffuse && "glass-diffuse",
      diffuse === "stained" && "glass-stained",
      gradient && "glass-gradient",
      glow === "lg" ? "glass-glow-lg" : glow ? "glass-glow" : false,
      sheen && "glass-sheen",
    ]
      .filter(Boolean)
      .join(" "),
  };
}

/**
 * The component-facing resolver: merge a component's ROLE (its default axes for a given semantic
 * variant) with explicit per-instance material/axis props, and return the surface markup — or null
 * when the element is NOT a glass surface (role === null, or material === "none").
 *
 * Explicit props override the role per-axis; unspecified axes fall back to the role.
 */
export function materialSurface(role: MaterialProps | null, props: MaterialProps): MaterialAttrs | null {
  if (props.material === "none" || role === null) {
    return null;
  }
  return glassMaterial({
    material: props.material,
    border: props.border ?? role.border,
    borderColor: props.borderColor ?? role.borderColor,
    veil: props.veil ?? role.veil,
    size: props.size ?? role.size,
    diffuse: props.diffuse ?? role.diffuse,
    gradient: props.gradient ?? role.gradient,
    glow: props.glow ?? role.glow,
    sheen: props.sheen ?? role.sheen,
  });
}

/**
 * Typed per-element knobs → CSS custom properties ONLY (the cascade-native successor to the old
 * `glass={{…}}` inline-style prop). Everything routes through the token system, so nothing here can
 * fight a material, a page style, or the theme.
 *
 * The tint* keys recolor engine-composed tokens, which re-resolve at grouped declarations — pair
 * them with a `data-glass-tint` attribute on the same element so the engine re-composes there.
 */
export interface GlassVars {
  /** → --glass-tint-h (surface hue) */
  tintH?: number;
  /** → --glass-tint-c (surface chroma — the colorfulness master) */
  tintC?: number;
  /** → --glass-tint-a (tint film alpha) */
  tintA?: number;
  /** → --glass-opacity (0..1 solidify dial; element-composed in `glass`) */
  opacity?: number;
  /** → --srf-blur (number → px; glass material only) */
  blur?: number | string;
  /** → --glass-solid-a (veil floor alpha; element-composed in `glass-veil`) */
  solidA?: number;
}

export function glassVars(v: GlassVars = {}): React.CSSProperties {
  const s: Record<string, string> = {};
  if (v.tintH !== undefined) {
    s["--glass-tint-h"] = String(v.tintH);
  }
  if (v.tintC !== undefined) {
    s["--glass-tint-c"] = String(v.tintC);
  }
  if (v.tintA !== undefined) {
    s["--glass-tint-a"] = String(v.tintA);
  }
  if (v.opacity !== undefined) {
    s["--glass-opacity"] = String(v.opacity);
  }
  if (v.blur !== undefined) {
    s["--srf-blur"] = typeof v.blur === "number" ? `${v.blur}px` : v.blur;
  }
  if (v.solidA !== undefined) {
    s["--glass-solid-a"] = String(v.solidA);
  }
  return s as React.CSSProperties;
}

import { cva } from "class-variance-authority";

/**
 * Shared hover effect variants for all Sistine components
 *
 * Effects:
 * - none: No hover effect
 * - glow: Themed glow shadow (--glass-glow, follows the tint hue) that intensifies on hover
 * - shimmer: Moving shimmer effect across the component
 * - ripple: Ripple effect that scales outward on hover
 * - lift: Subtle lift effect with shadow increase
 * - scale: Scale up slightly on hover
 */
export const hoverEffects = cva("transition duration-300", {
  variants: {
    hover: {
      none: "",
      glow: "glass-glow hover:glass-glow-lg",
      shimmer:
        "relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:bg-gradient-to-r before:from-transparent before:via-white/20 before:to-transparent hover:before:translate-x-full before:transition-transform before:duration-1000",
      ripple:
        "relative overflow-hidden after:absolute after:inset-0 after:scale-0 after:rounded-full after:bg-white/30 after:transition-transform after:duration-500 hover:after:scale-150",
      lift: "hover:-translate-y-1 hover:shadow-lg",
      scale: "hover:scale-105",
    },
  },
  defaultVariants: {
    hover: "none",
  },
});

export type HoverEffect = "none" | "glow" | "shimmer" | "ripple" | "lift" | "scale";

"use client";

import { CheckCircleIcon, CircleNotchIcon, InfoIcon, WarningIcon, WarningOctagonIcon } from "@phosphor-icons/react";
import { useTheme } from "next-themes";
import * as React from "react";
import { Toaster as Sonner, type ToastClassnames } from "sonner";
import { glassMaterial } from "@/lib/material";
import { cn } from "@/lib/utils";

type ToasterProps = React.ComponentProps<typeof Sonner>;

/**
 * sonner's `data-type` → the theme's status tint. A status toast is stamped `data-glass-tint="<tint>"`,
 * which is all it takes for the glass engine to re-resolve the toast's surface in that status hue (the
 * same blocks Alert and the destructive Button use). sonner calls the destructive status "error".
 * Default and loading toasts are not stamped, so they follow the page's tint.
 */
export const TOAST_TINT: Record<string, string> = {
  success: "success",
  error: "destructive",
  warning: "warning",
  info: "info",
};

/* Role: bordered + veiled glass at the elevated tier, like every other read-through overlay. */
const SURFACE = glassMaterial({
  border: true,
  veil: true,
  size: "lg",
});
const BUTTON = glassMaterial({
  border: true,
  size: "sm",
});

/* The layout sonner draws itself when it is styled, rebuilt in classes because the Toaster is
   `unstyled`: sonner's own stylesheet is unlayered, so with it active no Tailwind utility (the glass
   surface included) could win against it, and the theme had to carry `[data-sonner-toast]` overrides
   with !important. Unstyled, sonner keeps positioning, stacking, swiping and animation, and the look
   comes from the material system like every other component. */
const CLASS_NAMES: ToastClassnames = {
  toast: cn(
    SURFACE.className,
    "group toast flex w-(--width) items-center gap-1.5 rounded-xl p-4 text-[13px] text-foreground",
    /* A collapsed stack shows only the front toast's content; the ones behind are bare surfaces. */
    "[&[data-expanded=false][data-front=false]>*]:opacity-0",
    /* Status edge in the toast's own status hue (the stamped tint resolves --glass-tint-h here).
       `!` on the colour itself, not the --srf-border-color slot: the page styles remap that slot from
       unlayered rules that match the toast too (it carries data-glass-tint), so no utility could win. */
    "data-[glass-tint]:border-[oklch(0.7_0.18_var(--glass-tint-h)/0.3)]!",
  ),
  icon: "relative flex size-4 shrink-0 items-center justify-start ml-(--toast-icon-margin-start) mr-(--toast-icon-margin-end)",
  content: "flex min-w-0 flex-1 flex-col gap-0.5",
  title: "font-medium leading-normal",
  /* `!`: sonner colours a dark-theme description from an unlayered rule that is not gated on styling. */
  description: "font-normal leading-[1.4] text-muted-foreground!",
  actionButton: cn(
    BUTTON.className,
    "ml-(--toast-button-margin-start) mr-(--toast-button-margin-end) flex h-6 shrink-0 cursor-pointer items-center rounded-md px-2 text-xs font-medium text-foreground transition-opacity outline-hidden hover:opacity-90 focus-visible:ring-2 focus-visible:ring-ring/50",
  ),
  cancelButton: cn(
    BUTTON.className,
    "ml-(--toast-button-margin-start) mr-(--toast-button-margin-end) flex h-6 shrink-0 cursor-pointer items-center rounded-md px-2 text-xs font-medium text-muted-foreground transition-opacity outline-hidden hover:opacity-90 focus-visible:ring-2 focus-visible:ring-ring/50",
  ),
  closeButton: cn(
    BUTTON.className,
    "absolute top-0 right-(--toast-close-button-end) left-(--toast-close-button-start) z-[1] flex size-5 cursor-pointer items-center justify-center rounded-full p-0 text-foreground [transform:var(--toast-close-button-transform)] hover:opacity-90",
  ),
  success:
    "[&_[data-title]]:text-green-600 dark:[&_[data-title]]:text-green-400 [&_[data-description]]:text-green-600/80! dark:[&_[data-description]]:text-green-400/80! [&_[data-icon]]:text-green-600! dark:[&_[data-icon]]:text-green-400!",
  error:
    "[&_[data-title]]:text-red-600 dark:[&_[data-title]]:text-red-400 [&_[data-description]]:text-red-600/80! dark:[&_[data-description]]:text-red-400/80! [&_[data-icon]]:text-red-600! dark:[&_[data-icon]]:text-red-400!",
  warning:
    "[&_[data-title]]:text-yellow-600 dark:[&_[data-title]]:text-yellow-400 [&_[data-description]]:text-yellow-600/80! dark:[&_[data-description]]:text-yellow-400/80! [&_[data-icon]]:text-yellow-600! dark:[&_[data-icon]]:text-yellow-400!",
  info: "[&_[data-title]]:text-blue-600 dark:[&_[data-title]]:text-blue-400 [&_[data-description]]:text-blue-600/80! dark:[&_[data-description]]:text-blue-400/80! [&_[data-icon]]:text-blue-600! dark:[&_[data-icon]]:text-blue-400!",
};

/** Merge a consumer's classNames over ours key by key, so passing one key does not drop the rest. */
function mergeClassNames(theirs: ToastClassnames | undefined): ToastClassnames {
  if (!theirs) return CLASS_NAMES;
  const out: Record<string, string | undefined> = {
    ...CLASS_NAMES,
  };
  for (const [key, value] of Object.entries(theirs)) out[key] = cn(out[key], value);
  return out as ToastClassnames;
}

/** Stamp (or clear) each toast's status tint from its `data-type`. */
function stampTints(root: ParentNode) {
  for (const el of root.querySelectorAll<HTMLElement>("[data-sonner-toast]")) {
    const tint = TOAST_TINT[el.dataset.type ?? ""];
    if (tint) {
      if (el.dataset.glassTint !== tint) el.dataset.glassTint = tint;
    } else if (el.dataset.glassTint !== undefined) {
      delete el.dataset.glassTint;
    }
  }
}

/**
 * Sistine Toaster - toast notifications on the glass material.
 *
 * Each toast is a bordered, veiled glass surface; status toasts (success / error / warning / info) take
 * their status hue. sonner renders the toasts, so it cannot be handed per-toast attributes: an observer
 * on the toaster stamps `data-glass-tint` from each toast's `data-type`, including when a promise toast
 * settles from loading into success or error. It runs as a microtask after sonner's DOM write, so a
 * toast never paints untinted.
 *
 * @example
 * ```tsx
 * import { Toaster } from "@/components/ui/sonner"
 * import { toast } from "sonner"
 *
 * // Add to root layout
 * <Toaster />
 *
 * // Use in components
 * toast.success('Success!', { description: 'Your action completed' })
 * ```
 */
/* The toaster follows the APP's theme (next-themes, which the site's light / dark toggle drives), as
   shadcn's does; an explicit `theme` prop still wins, and without a ThemeProvider it falls back to the OS
   ("system"). It used to default to "system" outright, so sonner's data-sonner-theme tracked the OS and
   ignored the toggle: a light-mode page on a dark-mode OS got dark-theme toasts. */
const Toaster = ({ theme, toastOptions, ref, ...props }: ToasterProps) => {
  // A forced theme (next-themes' forcedTheme, e.g. a page pinned dark) wins over the stored choice, as it
  // does for the page itself; a stored "system" is resolved by sonner exactly as next-themes resolves it.
  const { theme: chosenTheme, forcedTheme } = useTheme();
  const appTheme = forcedTheme ?? chosenTheme;
  const sectionRef = React.useRef<HTMLElement | null>(null);
  const setRef = React.useCallback(
    (node: HTMLElement | null) => {
      sectionRef.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [
      ref,
    ],
  );

  React.useEffect(() => {
    const section = sectionRef.current;
    if (!section) return;
    stampTints(section);
    /* Only data-type is watched: our own data-glass-tint write cannot retrigger the observer. */
    const observer = new MutationObserver(() => stampTints(section));
    observer.observe(section, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeFilter: [
        "data-type",
      ],
    });
    return () => observer.disconnect();
  }, []);

  return (
    <Sonner
      ref={setRef}
      theme={(theme ?? appTheme ?? "system") as ToasterProps["theme"]}
      className="toaster group"
      icons={{
        success: <CheckCircleIcon className="size-4" />,
        info: <InfoIcon className="size-4" />,
        warning: <WarningIcon className="size-4" />,
        error: <WarningOctagonIcon className="size-4" />,
        loading: <CircleNotchIcon className="size-4 animate-spin" />,
      }}
      toastOptions={{
        ...toastOptions,
        unstyled: true,
        classNames: mergeClassNames(toastOptions?.classNames),
      }}
      {...props}
    />
  );
};

export { Toaster };
